import {
  cancelGeneration,
  activateAiModel,
  completeBookMetadata,
  createAiModel,
  createGeneration,
  deleteAiModel,
  getAiConfig,
  getAiTemplate,
  getAiModels,
  getAiTemplates,
  getCategories,
  getGeneration,
  getGenerations,
  publishBook,
  publishGeneration,
  regenerateSection,
  saveBookDraft,
  saveGenerationDraft,
  testAiModel,
  updateAiModel,
  updateAiTemplate,
} from './studio-api.js?v=5';

const initialHtml='';

const state={
  mode:'ai',
  bookMeta:{slug:'',title:'',author:'',category:'',description:'',tags:[],status:'draft',coverUrl:''},
  htmlContent:initialHtml,previewHtml:initialHtml,validationResult:{},splitRatio:65,previewDevice:'desktop',isFullscreenPreview:false,mobilePane:'edit',
  importMeta:{fileName:'',structure:'等待导入',duplicate:'暂未启用'},prompt:'',
  aiConfig:null,aiModels:[],templates:[],categories:[],history:[],generation:null,syncToGit:false,aiError:'',pollTimer:null,settingsOpen:false,modelMessage:'',templateEditorOpen:false,templateMessage:'',metadataLoading:false,contentDirectoryHandle:null,
  modelForm:{id:'',apiFormat:'openai-chat-completions',baseUrl:'https://api.openai.com/v1',useFullUrl:false,modelId:'',displayName:'',apiKey:'',activate:true},
  templateForm:null,
  aiForm:{templateId:'ten-minute-reading',sourceText:'',modules:[],audience:'',style:'',length:'medium',allowBackgroundKnowledge:false}
};

const esc=s=>String(s??'').replace(/[&<>"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]));
const metaValue=(doc,name)=>doc.querySelector(`meta[name="${name}"]`)?.getAttribute('content')?.trim()||'';
const fallbackCategories=[['fantasy','幻想文学'],['science-fiction','科幻宇宙'],['literature','文学经典'],['philosophy','哲学思想'],['history','历史人文'],['other','其他']];
function availableCategories(){return state.categories.length?state.categories:fallbackCategories.map(([slug,name])=>({slug,name,description:null}))}
function CategoryOptions(){return availableCategories().map(item=>`<option value="${esc(item.name)}" ${item.name===state.bookMeta.category?'selected':''}>${esc(item.name)}</option>`).join('')}

function parseHtml(html,{apply=true}={}){
  const doc=new DOMParser().parseFromString(html,'text/html');
  const found={title:doc.querySelector('title')?.textContent?.trim()||'',author:metaValue(doc,'author'),category:metaValue(doc,'category'),description:metaValue(doc,'description'),tags:metaValue(doc,'keywords').split(',').map(x=>x.trim()).filter(Boolean)};
  if(apply){['title','author','category','description'].forEach(k=>{if(found[k])state.bookMeta[k]=found[k]});if(found.tags.length)state.bookMeta.tags=found.tags}
  state.validationResult={title:Boolean(found.title||state.bookMeta.title),author:Boolean(found.author||state.bookMeta.author),category:Boolean(found.category||state.bookMeta.category),html:Boolean(doc.documentElement&&doc.body&&!doc.querySelector('parsererror')),cover:Boolean(state.bookMeta.coverUrl)};
  return found;
}

function WorkshopHeader(){return `<header class="workshop-header"><div><span class="workshop-kicker">CONTENT CREATION DESK</span><h1>AI 工坊</h1><p>创建、生成并导入你的书籍内容</p></div><blockquote>所有伟大的故事，<br>都从一个念头开始。</blockquote></header>`}
function relativeTaskTime(value){if(!value)return '暂无';const seconds=Math.max(1,Math.floor((Date.now()-new Date(value).getTime())/1000));if(seconds<60)return '刚刚';if(seconds<3600)return `${Math.floor(seconds/60)} 分钟前`;if(seconds<86400)return `${Math.floor(seconds/3600)} 小时前`;return `${Math.floor(seconds/86400)} 天前`}
function WorkshopStats(){const active=state.history.filter(item=>['queued','generating','reviewing'].includes(item.status)).length;const completed=state.history.filter(item=>item.status==='completed').length;const latest=state.history[0];return `<section class="workshop-statusbar" id="workshopStats" aria-label="工作台概览"><span>模板 <b>${state.templates.length||'—'}</b></span><i>·</i><span>进行中 <b>${active}</b></span><i>·</i><span>已完成 <b>${completed}</b></span><i>·</i><button type="button" data-open-history>最近任务 ${relativeTaskTime(latest?.updatedAt||latest?.createdAt)}</button></section>`}
function CreationModeTabs(){const tabs=[['ai','✦','AI 生成'],['manual','▤','手动创建'],['import','⇧','导入 HTML'],['history','▧','任务记录']];return `<nav class="creation-tabs" aria-label="AI 工坊功能">${tabs.map(([id,ic,label])=>`<button data-creation-mode="${id}" class="${state.mode===id?'active':''}"><i>${ic}</i><span>${label}</span></button>`).join('')}</nav>`}

function BookMetaForm({compact=false}={}){return `<section class="meta-form ${compact?'compact':''}"><header><span>▣</span><div><h2>书籍基本信息</h2><p>${compact?'检查并修改自动识别的结果':'填写核心元信息，方便整理与管理'}</p></div></header><div class="meta-grid"><label><b>书名 <em>*</em></b><input data-meta="title" value="${esc(state.bookMeta.title)}" placeholder="请输入书名"></label><label><b>Slug <em>*</em></b><input data-meta="slug" value="${esc(state.bookMeta.slug)}" placeholder="例如 my-book"></label><label><b>作者</b><input data-meta="author" value="${esc(state.bookMeta.author)}" placeholder="请输入作者"></label><label><b>分类</b><select data-meta="category">${CategoryOptions()}</select></label><label class="description-field"><b>简介</b><input data-meta="description" value="${esc(state.bookMeta.description)}" placeholder="可选"></label><div class="tag-field"><b>标签</b><div class="editable-tags">${state.bookMeta.tags.map((x,i)=>`<button data-remove-tag="${i}" title="删除标签">${esc(x)}　×</button>`).join('')}<button class="add-tag" data-add-tag>＋ 添加标签</button></div></div><div class="status-field"><b>状态</b><label><input type="radio" name="workshop-status" value="draft" ${state.bookMeta.status==='draft'?'checked':''}> 草稿</label><label><input type="radio" name="workshop-status" value="published" ${state.bookMeta.status==='published'?'checked':''}> 已发布</label></div>${compact?'':`<div class="cover-field"><b>封面（可选）</b><label class="cover-picker"><input id="coverInput" type="file" accept="image/png,image/jpeg,image/webp"><span class="cover-preview" id="coverPreview" ${state.bookMeta.coverUrl?`style="background-image:url('${state.bookMeta.coverUrl}')"`:''}>${state.bookMeta.coverUrl?'':'▧<small>选择本地图片</small>'}</span></label><small>保存到内容目录时会一并写入</small></div>`}</div></section>`}

function HtmlEditor(){const lines=Math.max(1,state.htmlContent.split('\n').length);return `<section class="html-editor-panel"><header><div><h2>&lt;/&gt;　HTML 内容</h2><p>支持完整 HTML，预览在隔离环境中运行</p></div><div class="editor-tools"><button data-paste-html>粘贴完整 HTML</button><button data-recognize>从 HTML 识别信息</button><button data-format>格式化</button></div></header><div class="html-editor-shell"><pre class="editor-lines" id="editorLines">${Array.from({length:lines},(_,i)=>i+1).join('\n')}</pre><textarea id="workshopHtml" spellcheck="false" aria-label="HTML 内容">${esc(state.htmlContent)}</textarea></div></section>`}
function GitSyncOption(){return `<label class="git-sync-option"><input type="checkbox" data-sync-git ${state.syncToGit?'checked':''}> 发布后同步到 Git</label>`}
function WorkbenchActions({primary='发布到书库',preview=true}={}){return `<div class="workshop-actionbar"><div>${preview?'<button type="button" data-open-preview>预览</button>':''}<button type="button" data-export-content>导出到本地 Git 目录</button></div><div>${GitSyncOption()}<button type="button" data-save>保存草稿</button><button type="button" class="primary" data-publish>${primary}</button></div></div>`}
function ManualCreatePanel(){return `<div class="manual-create-panel"><header class="mode-heading"><div><small>MANUAL EDITOR</small><h2>手动创建</h2></div><p>集中编辑元数据和完整正文，预览仅在需要时打开。</p></header>${BookMetaForm()}${HtmlEditor()}${WorkbenchActions()}</div>`}

function ImportHtmlPanel(){const parsed=state.importMeta.structure!=='等待导入';return `<section class="import-panel"><header class="mode-heading"><div><small>HTML IMPORTER</small><h2>导入 HTML</h2></div><p>上传或粘贴 HTML，完成解析与校验后再确认导入。</p></header><section class="workshop-form-section"><div class="section-heading"><span>01</span><div><h3>上传或粘贴</h3><p>支持 .html / .htm 文件，也可直接粘贴完整代码。</p></div></div><label class="drop-zone" id="dropZone"><input id="htmlFileInput" type="file" accept=".html,.htm,text/html"><span>⇧</span><b>拖入 HTML 文件</b><small>或点击选择文件</small></label><div class="import-or"><span>或</span></div><label class="paste-import"><b>粘贴 HTML</b><textarea id="importHtmlText" placeholder="在这里粘贴完整 HTML…">${state.importMeta.fileName?'':esc(state.htmlContent)}</textarea><button data-parse-paste>解析粘贴内容</button></label></section><section class="workshop-form-section"><div class="section-heading"><span>02</span><div><h3>解析与校验</h3><p>检查识别出的元数据和 HTML 结构。</p></div></div><div class="recognized-result ${parsed?'':'waiting'}"><header><h3>识别结果</h3><span>${esc(state.importMeta.fileName||'尚未选择文件')}</span></header>${BookMetaForm({compact:true})}<dl><div><dt>文件名</dt><dd>${esc(state.importMeta.fileName||'—')}</dd></div><div><dt>HTML 结构状态</dt><dd>${esc(state.importMeta.structure)}</dd></div><div><dt>重复检测</dt><dd>${esc(state.importMeta.duplicate)}</dd></div></dl></div>${parsed?ValidationList():''}</section>${WorkbenchActions({primary:'确认导入',preview:parsed})}</section>`}

function selectedTemplate(){return state.templates.find(template=>template.id===state.aiForm.templateId)||state.templates[0]}
function makePrompt(){const template=selectedTemplate();const modules=template?.modules.filter(item=>state.aiForm.modules.includes(item.key)).map(item=>item.title).join('、')||'默认模块';return `请基于我提供的资料，为《${state.bookMeta.title||'未命名书籍'}》整理结构化内容。\n作者：${state.bookMeta.author||'未填写'}\n分类：${state.bookMeta.category||'未填写'}\n模板：${template?.name||'默认模板'}\n包含模块：${modules}\n目标读者：${state.aiForm.audience||'未指定，使用模板默认'}\n写作风格：${state.aiForm.style||'未指定，使用模板默认'}\n要求：严格区分资料事实和推论，不编造引文。`}
function GenerationProgress(){const task=state.generation;if(!task)return '';const terminal=['completed','failed','cancelled'].includes(task.status);return `<section class="generation-progress ${esc(task.status)}"><header><div><h3>${esc(task.title)}</h3><p>${esc(task.currentStep||task.status)}</p></div><strong>${task.progress}%</strong></header><div class="generation-progress__bar"><i style="width:${Number(task.progress)||0}%"></i></div>${task.error?`<p class="generation-error">${esc(task.error)}</p>`:''}<footer>${!terminal?'<button data-ai-cancel>取消任务</button>':''}${task.status==='completed'?'<span>AI 草稿已自动保存，刷新页面后会自动恢复。</span>':''}</footer></section>`}
const blockTypeLabels={lead:'导语',paragraph:'正文',quote:'引用',callout:'重点',cards:'卡片',steps:'步骤',comparison:'对照',checklist:'清单',tags:'标签',stats:'数据'};
function GeneratedSections(){const task=state.generation;if(task?.status!=='completed'||!task.result?.sections)return '';return `<section class="generated-sections"><header><h3>生成内容</h3><span>${task.result.sections.length} 个模块</span></header>${task.result.sections.map(section=>`<article><div><b>${esc(section.title)}</b><button data-regenerate-section="${esc(section.key)}">重新生成</button></div>${section.blocks?.length?`<div class="generated-block-types">${section.blocks.map(block=>`<span>${esc(blockTypeLabels[block.type]||block.type)}</span>`).join('')}</div>`:''}<p>${esc(section.content)}</p></article>`).join('')}</section>`}
function GenerationHistory(){if(!state.history.length)return '';return `<section class="generation-history"><header><h3>最近任务</h3></header>${state.history.slice(0,8).map(task=>`<article><div><span><b>${esc(task.title)}</b><small>${new Date(task.createdAt).toLocaleString()}</small></span><em>${esc(task.status)} · ${task.progress}%</em></div>${task.error?`<p>${esc(task.error)}</p>`:''}<footer><button data-load-generation="${task.id}">${task.status==='failed'?'载入并重试':'查看任务'}</button></footer></article>`).join('')}</section>`}
function TaskHistoryPanel(){return `<section class="ai-panel task-history-panel"><header class="mode-heading"><div><small>TASK HISTORY</small><h2>任务记录</h2></div><p>查看生成与导入历史、状态和错误信息；失败任务可载入后重试。</p></header>${GenerationHistory()||'<div class="generation-history empty"><p>暂无生成任务。导入和手动创建仍会保留在当前浏览器草稿中。</p></div>'}</section>`}
function AiGeneratePanel(){
  const template=selectedTemplate();
  const configured=state.aiConfig?.configured;
  const statusLabel=state.aiConfig?`${state.aiConfig.provider}${state.aiConfig.displayName||state.aiConfig.model?` / ${state.aiConfig.displayName||state.aiConfig.model}`:''}`:'正在连接 API…';
  const completed=state.generation?.status==='completed';
  return `<section class="ai-panel"><header class="mode-heading"><div><small>AI GENERATOR</small><h2>AI 生成</h2></div><p>按阶段提供信息，让生成过程和结果保持在同一条工作流中。</p></header>
    <div class="service-strip"><span class="dev-badge ${configured?'ready':'warning'}">${configured?'已连接':'待配置'}</span><b>模型服务</b><span>${esc(statusLabel)}</span>${state.aiError?`<em>${esc(state.aiError)}</em>`:''}<button type="button" data-open-model-settings>配置模型</button><button type="button" data-open-login>账号登录</button></div>
    <section class="workshop-form-section"><div class="section-heading"><span>01</span><div><h3>基础信息</h3><p>用于识别、保存和归档这本书。</p></div></div><div class="ai-form">
      <label class="ai-title-field"><span><b>书名 <em>*</em></b><button type="button" data-ai-fill-metadata ${configured&&!state.metadataLoading?'':'disabled'}>${state.metadataLoading?'AI 填写中…':'✦ AI 填写作者与 Slug'}</button></span><input data-meta="title" value="${esc(state.bookMeta.title)}" placeholder="输入书名后点击 AI 填写" required></label><label><b>作者</b><input data-meta="author" value="${esc(state.bookMeta.author)}" placeholder="可由 AI 自动填写"></label>
      <label><b>Slug</b><input data-meta="slug" value="${esc(state.bookMeta.slug)}" placeholder="my-book"></label><label><b>分类</b><select data-meta="category">${CategoryOptions()}</select></label>
    </div></section>
    <section class="workshop-form-section"><div class="section-heading"><span>02</span><div><h3>生成设置</h3><p>选择内容结构、篇幅与表达方式。</p></div></div><div class="ai-form">
      <label class="template-select-field"><span><b>模板</b><button type="button" data-edit-template ${template?'':'disabled'}>编辑当前模板</button></span><select data-ai-template>${state.templates.length?state.templates.map(item=>`<option value="${esc(item.id)}" ${item.id===state.aiForm.templateId?'selected':''}>${esc(item.name)}</option>`).join(''):'<option>正在加载模板…</option>'}</select><small>${esc(template?.description||'选择生成内容的组织方式')}</small></label>
      <label><b>篇幅</b><select data-ai-field="length"><option value="short" ${state.aiForm.length==='short'?'selected':''}>精简</option><option value="medium" ${state.aiForm.length==='medium'?'selected':''}>标准</option><option value="long" ${state.aiForm.length==='long'?'selected':''}>详细</option></select></label>
    </div></section>
    <section class="workshop-form-section"><div class="section-heading"><span>03</span><div><h3>参考资料（可选）</h3><p>留空时 AI 将依据通用知识生成；提供资料可提高准确性。</p></div></div><label class="ai-source"><b>文本输入</b><textarea data-ai-field="sourceText" placeholder="可选：粘贴可信资料、摘录、提纲或个人笔记…">${esc(state.aiForm.sourceText)}</textarea><small>可留空，最多 100,000 字符</small></label><div class="reference-actions"><button type="button" data-switch-import>通过文件 / HTML 导入</button><span>来源链接：当前版本暂不支持自动抓取</span></div></section>
    <details class="advanced-settings"><summary><span>高级设置</span><small>目标读者、写作风格、内容模块与 Prompt 摘要</small></summary><div><div class="advanced-writing-fields"><label><b>目标读者（可选）</b><input data-ai-field="audience" value="${esc(state.aiForm.audience)}" placeholder="例如：刚接触本主题的普通读者"></label><label><b>写作风格（可选）</b><input data-ai-field="style" value="${esc(state.aiForm.style)}" placeholder="例如：通俗、简洁、有叙事感"></label></div><fieldset><legend>内容模块</legend>${template?template.modules.map(item=>`<label><input type="checkbox" data-ai-module="${esc(item.key)}" ${state.aiForm.modules.includes(item.key)?'checked':''}> ${esc(item.title)}</label>`).join(''):'<span>模板加载后显示模块</span>'}</fieldset><label class="ai-background"><input type="checkbox" data-ai-field="allowBackgroundKnowledge" ${state.aiForm.allowBackgroundKnowledge?'checked':''}> 允许补充背景知识，但必须明确标注</label><div class="prompt-tools"><button data-generate-prompt>查看 Prompt 摘要</button><button data-copy-prompt>复制摘要</button></div><div class="prompt-output" id="promptOutput">${esc(state.prompt)}</div></div></details>
    ${GenerationProgress()}${completed?`<section class="generation-result"><div><i>✓</i><span><b>内容生成完成</b><small>结果已准备好，可预览、继续编辑或发布。</small></span></div><div><button data-open-preview>预览</button><button data-switch-manual>编辑</button><button class="primary" data-publish>发布到书库</button></div></section>`:''}${GeneratedSections()}
    <div class="workshop-actionbar"><span>生成结果会自动保存，刷新后可恢复</span><div>${completed?GitSyncOption():''}<button type="button" data-save>保存草稿</button><button class="primary" data-ai-generate ${configured&&template?'':'disabled'}>${state.generation&&!completed?'继续生成':'开始生成'}</button></div></div>
  </section>`
}

function AiModelSettings(){
  if(!state.settingsOpen)return '<div id="aiModelSettings"></div>';
  const form=state.modelForm;
  const editingModel=state.aiModels.find(model=>model.id===form.id);
  return `<div class="model-settings-backdrop" id="aiModelSettings" role="dialog" aria-modal="true" aria-labelledby="modelSettingsTitle">
    <section class="model-settings-modal">
      <header><div><small>AI MODEL SETTINGS</small><h2 id="modelSettingsTitle">${form.id?'编辑模型':'自定义模型'}</h2></div><button type="button" data-close-model-settings aria-label="关闭">×</button></header>
      <div class="model-settings-layout">
        <aside><div class="model-list-heading"><b>已保存模型</b><button type="button" data-new-model>＋ 新增</button></div>${state.aiModels.length?state.aiModels.map(model=>`<button type="button" class="model-list-item ${model.id===form.id?'selected':''}" data-edit-model="${esc(model.id)}"><span><b>${esc(model.displayName)}</b><small>${esc(model.modelId)}</small></span>${model.isActive?'<em>当前</em>':''}</button>`).join(''):'<p class="model-list-empty">还没有保存的模型</p>'}</aside>
        <form class="model-settings-form" id="modelSettingsForm">
          <label><b>API 格式 <em>*</em></b><select data-model-field="apiFormat"><option value="openai-chat-completions" selected>OpenAI Chat Completions</option></select></label>
          <label><span><b>自定义请求 URL <em>*</em></b><span class="full-url-switch"><input type="checkbox" data-model-field="useFullUrl" ${form.useFullUrl?'checked':''}> 完整 URL</span></span><input type="url" data-model-field="baseUrl" value="${esc(form.baseUrl)}" placeholder="例如 https://api.openai.com/v1" required><small>${form.useFullUrl?'将直接请求此 URL。':'系统会自动在 URL 后追加 /chat/completions。'}</small></label>
          <label><b>模型 ID <em>*</em></b><input data-model-field="modelId" value="${esc(form.modelId)}" placeholder="例如 gpt-5-mini" maxlength="160" required></label>
          <label><b>显示名称</b><input data-model-field="displayName" value="${esc(form.displayName)}" placeholder="留空则使用模型 ID" maxlength="160"></label>
          <label><b>API Key ${form.id?'':'<em>*</em>'}</b><input type="password" data-model-field="apiKey" value="" placeholder="${form.id?'留空以保留已保存的密钥':'输入 API Key'}" autocomplete="new-password"><small>密钥由服务端加密保存，保存后不会再次返回浏览器。</small></label>
          <label class="activate-model"><input type="checkbox" data-model-field="activate" ${form.activate?'checked':''}> 保存后设为当前模型</label>
          ${state.modelMessage?`<p class="model-settings-message">${esc(state.modelMessage)}</p>`:''}
          <footer><span>${form.id?'<button type="button" class="danger" data-delete-model>删除</button>':''}</span><div>${form.id&&!editingModel?.isActive?'<button type="button" data-activate-model>设为当前</button>':''}${form.id?'<button type="button" data-test-model>测试连接</button>':''}<button type="button" data-reset-model>重置</button><button type="submit" class="primary">${form.id?'保存修改':'添加模型'}</button></div></footer>
        </form>
      </div>
    </section>
  </div>`;
}

function TemplateEditor(){
  if(!state.templateEditorOpen||!state.templateForm)return '<div id="templateEditor"></div>';
  const form=state.templateForm;
  return `<div class="template-editor-backdrop" id="templateEditor" role="dialog" aria-modal="true" aria-labelledby="templateEditorTitle"><form class="template-editor-modal" id="templateEditorForm"><header><div><small>CONTENT TEMPLATE</small><h2 id="templateEditorTitle">编辑模板 · ${esc(form.name)}</h2></div><button type="button" data-close-template-editor aria-label="关闭">×</button></header><main><section><h3>模板信息</h3><div class="template-editor-grid"><label><b>模板名称</b><input data-template-field="name" value="${esc(form.name)}" maxlength="120" required></label><label><b>内容类型</b><input data-template-field="contentType" value="${esc(form.contentType)}" maxlength="120" required></label><label class="wide"><b>说明</b><textarea data-template-field="description" maxlength="500">${esc(form.description)}</textarea></label><label class="wide"><b>系统提示词</b><textarea data-template-field="systemPrompt" required>${esc(form.systemPrompt)}</textarea></label></div></section><section><div class="template-module-heading"><div><h3>内容模块</h3><p>勾选默认启用项；模块标识用于历史任务兼容，不可修改。</p></div></div><div class="template-module-list">${form.modules.map((module,index)=>`<article><label class="module-default"><input type="checkbox" data-template-default="${index}" ${form.defaultModules.includes(module.key)?'checked':''}> 默认</label><label><b>模块名称</b><input data-template-module-field="title" data-template-module-index="${index}" value="${esc(module.title)}" required></label><label class="module-instruction"><b>生成要求</b><textarea data-template-module-field="instruction" data-template-module-index="${index}" required>${esc(module.instruction)}</textarea></label><code>${esc(module.key)}</code></article>`).join('')}</div></section>${state.templateMessage?`<p class="template-editor-message">${esc(state.templateMessage)}</p>`:''}</main><footer><span>保存后立即用于新的生成任务</span><div><button type="button" data-close-template-editor>取消</button><button type="submit" class="primary">保存模板</button></div></footer></form></div>`;
}

function ValidationList(){const v=state.validationResult;const items=[['title','书名识别成功'],['author','作者识别成功'],['category','分类识别成功'],['html','HTML 结构正常']];return `<section class="validation-list"><header><h3>内容校验结果</h3><button data-revalidate>重新校验</button></header>${items.map(([key,label])=>`<div class="${v[key]?'valid':'muted'}"><i>${v[key]?'✓':'—'}</i><span>${label}</span></div>`).join('')}<div class="warning"><i>!</i><span>${v.cover?'封面已选择':'封面建议确认'}</span></div></section>`}
function DevicePreviewSwitch(){return `<div class="device-switch">${[['desktop','桌面'],['tablet','平板'],['mobile','手机']].map(([id,label])=>`<button data-device="${id}" class="${state.previewDevice===id?'active':''}">${label}</button>`).join('')}</div>`}
function PreviewDrawer(){return `<section class="preview-drawer" id="previewDrawer" hidden aria-modal="true" role="dialog" aria-labelledby="previewDrawerTitle"><button class="preview-drawer__backdrop" type="button" data-close-preview aria-label="关闭预览"></button><aside><header><div><small>ISOLATED HTML PREVIEW</small><h2 id="previewDrawerTitle">内容预览</h2></div>${DevicePreviewSwitch()}<button class="preview-close" type="button" data-close-preview aria-label="关闭预览">×</button></header><main><div class="device-frame ${state.previewDevice}" id="deviceFrame"><iframe id="previewDrawerFrame" sandbox="" title="书籍内容预览"></iframe></div></main><footer>${ValidationList()}<div>${GitSyncOption()}<button data-export-content>导出到本地 Git 目录</button><button data-save>保存草稿</button><button class="primary" data-publish>发布到书库</button></div></footer></aside></section>`}
function SingleColumnWorkspace(){return `<main class="workshop-main"><div class="creation-panel-slot"></div></main>`}
function AiWorkshopPage(){return `<div class="ai-workshop-page">${WorkshopHeader()}${WorkshopStats()}<section class="workshop-surface">${CreationModeTabs()}${SingleColumnWorkspace()}</section>${PreviewDrawer()}${AiModelSettings()}${TemplateEditor()}</div>`}

function formatHtml(html){return html.replace(/>\s*</g,'>\n<').split('\n').reduce((out,line)=>{line=line.trim();if(/^<\//.test(line))out.level=Math.max(0,out.level-1);out.lines.push('  '.repeat(out.level)+line);if(/^<[^!/][^>]*[^/]>$/.test(line)&&!/<\/(?:[^>]+)>$/.test(line)&&!/^<(meta|link|img|input|br|hr)\b/i.test(line))out.level++;return out},{level:0,lines:[]}).lines.join('\n')}

export function createAiWorkshopPage(root,{showToast,bindNavigation}){
  if(state.pollTimer){clearInterval(state.pollTimer);state.pollTimer=null}
  parseHtml(state.htmlContent,{apply:false});root.innerHTML=AiWorkshopPage();bindNavigation?.();
  const slot=root.querySelector('.creation-panel-slot');
  let previewReturnFocus=null;
  const updatePreview=()=>{state.previewHtml=state.htmlContent;const frame=root.querySelector('#previewDrawerFrame');if(frame&&!root.querySelector('#previewDrawer')?.hidden)frame.srcdoc=state.previewHtml;root.querySelectorAll('.validation-list').forEach(validation=>validation.outerHTML=ValidationList());bindSharedActions()};
  const categoryInfo=()=>{const category=availableCategories().find(item=>item.name===state.bookMeta.category);return {categorySlug:category?.slug||'other',categoryName:category?.name||state.bookMeta.category||'其他'}};
  const validateBookInput=()=>{if(!state.bookMeta.title.trim())throw new Error('请填写书名');if(!/^[a-z0-9]+(?:-[a-z0-9]+)*$/.test(state.bookMeta.slug))throw new Error('Slug 只能使用小写字母、数字和连字符');if(!state.htmlContent.trim())throw new Error('HTML 内容不能为空')};
  const bookPayload=()=>({slug:state.bookMeta.slug,title:state.bookMeta.title.trim(),author:state.bookMeta.author.trim()||undefined,summary:state.bookMeta.description.trim()||undefined,tags:state.bookMeta.tags,...categoryInfo(),contentHtml:state.htmlContent});
  const writeHandle=async(directory,name,content)=>{const handle=await directory.getFileHandle(name,{create:true});const writable=await handle.createWritable();try{await writable.write(content)}finally{await writable.close()}};
  const rebuildBrowserContentIndex=async booksDirectory=>{const books=[];for await(const [name,handle] of booksDirectory.entries()){if(handle.kind!=='directory'||name.startsWith('.')||name.startsWith('_'))continue;try{const metadataFile=await(await handle.getFileHandle('book.json')).getFile();const metadata=JSON.parse(await metadataFile.text());if(metadata.schemaVersion!==1||metadata.slug!==name)continue;books.push({...metadata,coverUrl:`/content/books/${metadata.slug}/${metadata.cover}`,contentUrl:`/content/books/${metadata.slug}/content.html`})}catch{continue}}books.sort((left,right)=>String(right.publishedAt??'').localeCompare(String(left.publishedAt??''))||left.title.localeCompare(right.title,'zh-CN'));await writeHandle(booksDirectory,'index.json',`${JSON.stringify({schemaVersion:1,books},null,2)}\n`)};
  const placeholderCover=title=>`<svg xmlns="http://www.w3.org/2000/svg" width="600" height="840" viewBox="0 0 600 840" role="img" aria-label="${esc(title)}"><rect width="600" height="840" fill="#24384a"/><rect x="34" y="34" width="532" height="772" rx="8" fill="none" stroke="#d7c59b" stroke-width="3"/><text x="300" y="400" fill="#f5eedc" font-family="serif" font-size="44" text-anchor="middle">${esc(title)}</text><text x="300" y="470" fill="#d7c59b" font-family="sans-serif" font-size="20" text-anchor="middle">数字书房</text></svg>\n`;
  const writeBookToContentDirectory=async status=>{validateBookInput();if(!window.showDirectoryPicker)throw new Error('当前浏览器不支持直接写目录，请使用最新版 Chrome 或 Edge');let booksDirectory=state.contentDirectoryHandle;if(!booksDirectory){booksDirectory=await window.showDirectoryPicker({id:'digital-study-content-books',mode:'readwrite'});if(booksDirectory.name!=='books')throw new Error('请选择仓库中的 content/books 目录');state.contentDirectoryHandle=booksDirectory}const bookDirectory=await booksDirectory.getDirectoryHandle(state.bookMeta.slug,{create:true});let exists=false;try{await bookDirectory.getFileHandle('book.json');exists=true}catch(error){if(error.name!=='NotFoundError')throw error}if(exists&&!confirm(`content/books/${state.bookMeta.slug} 已存在，是否覆盖正文和元数据？`))return null;let cover='cover.svg',coverContent=placeholderCover(state.bookMeta.title);if(state.bookMeta.coverUrl){const response=await fetch(state.bookMeta.coverUrl);const blob=await response.blob();const extensions={'image/png':'png','image/jpeg':'jpg','image/webp':'webp'};const extension=extensions[blob.type]||'png';cover=`cover.${extension}`;coverContent=blob}const metadata={schemaVersion:1,slug:state.bookMeta.slug,title:state.bookMeta.title.trim(),author:state.bookMeta.author.trim()||undefined,summary:state.bookMeta.description.trim()||undefined,tags:state.bookMeta.tags,cover,status,category:{slug:categoryInfo().categorySlug,name:categoryInfo().categoryName},...(status==='published'?{publishedAt:new Date().toISOString()}:{})};await writeHandle(bookDirectory,'content.html',state.htmlContent);await writeHandle(bookDirectory,cover,coverContent);await writeHandle(bookDirectory,'book.json',`${JSON.stringify(metadata,null,2)}\n`);await rebuildBrowserContentIndex(booksDirectory);state.bookMeta.status=status;localStorage.setItem('digital-study-workshop-draft',JSON.stringify({bookMeta:state.bookMeta,htmlContent:state.htmlContent}));return `content/books/${state.bookMeta.slug}`};
  const showError=(error)=>{state.aiError=error instanceof Error?error.message:String(error);showToast(state.aiError)};
  const updateStats=()=>{const stats=root.querySelector('#workshopStats');if(stats)stats.outerHTML=WorkshopStats();root.querySelector('[data-open-history]')?.addEventListener('click',()=>{state.mode='history';root.querySelectorAll('[data-creation-mode]').forEach(item=>item.classList.toggle('active',item.dataset.creationMode==='history'));renderMode()})};
  const applyGeneration=(task)=>{state.generation=task;if(task?.id)localStorage.setItem('digital-study-last-generation-id',task.id);if(task?.result?.renderedHtml){state.htmlContent=task.result.renderedHtml;state.bookMeta.title=task.title||state.bookMeta.title;state.bookMeta.author=task.author||state.bookMeta.author;state.bookMeta.slug=task.slug||state.bookMeta.slug;state.bookMeta.description=task.result.summary||state.bookMeta.description;state.bookMeta.tags=task.result.tags||state.bookMeta.tags;parseHtml(state.htmlContent,{apply:false});updatePreview()}};
  const refreshHistory=async()=>{try{state.history=await getGenerations();updateStats()}catch(error){showError(error)}};
  const stopPolling=()=>{if(state.pollTimer){clearInterval(state.pollTimer);state.pollTimer=null}};
  const pollGeneration=(id)=>{stopPolling();const tick=async()=>{try{const task=await getGeneration(id);applyGeneration(task);renderMode();if(['completed','failed','cancelled'].includes(task.status)){stopPolling();await refreshHistory();renderMode()}}catch(error){stopPolling();showError(error);renderMode()}};void tick();state.pollTimer=setInterval(tick,1500)};
  const loadAiData=async()=>{try{const [config,templates,categories]=await Promise.all([getAiConfig(),getAiTemplates(),getCategories().catch(()=>[])]);state.aiConfig=config;state.templates=templates;state.categories=categories;if(state.categories.length&&!state.categories.some(item=>item.name===state.bookMeta.category))state.bookMeta.category=state.categories[0].name;const template=templates.find(item=>item.id==='ten-minute-reading')||templates.find(item=>item.id===state.aiForm.templateId)||templates[0];if(template){state.aiForm.templateId=template.id;const validModules=new Set(template.modules.map(item=>item.key));state.aiForm.modules=state.aiForm.modules.filter(module=>validModules.has(module));if(!state.aiForm.modules.length)state.aiForm.modules=[...template.defaultModules]}state.aiError='';updateStats();if(state.mode==='ai')renderMode();try{const [history,models]=await Promise.all([getGenerations(),getAiModels()]);state.history=history;state.aiModels=models;const lastId=localStorage.getItem('digital-study-last-generation-id');if(!state.generation&&lastId&&history.some(item=>item.id===lastId)){try{applyGeneration(await getGeneration(lastId))}catch{localStorage.removeItem('digital-study-last-generation-id')}}state.aiError='';updateStats();if(state.mode==='ai')renderMode();if(state.settingsOpen)renderSettings()}catch(error){showError(error);if(state.mode==='ai')renderMode()}}catch(error){showError(error);if(state.mode==='ai')renderMode()}};
  const bindMeta=()=>{root.querySelectorAll('[data-meta]').forEach(input=>input.addEventListener('input',()=>{state.bookMeta[input.dataset.meta]=input.value}));root.querySelectorAll('input[name="workshop-status"]').forEach(input=>input.addEventListener('change',()=>state.bookMeta.status=input.value));root.querySelectorAll('[data-remove-tag]').forEach(btn=>btn.addEventListener('click',()=>{state.bookMeta.tags.splice(Number(btn.dataset.removeTag),1);renderMode()}));root.querySelector('[data-add-tag]')?.addEventListener('click',()=>{const value=prompt('输入新标签');if(value?.trim()){state.bookMeta.tags.push(value.trim());renderMode()}});const cover=root.querySelector('#coverInput');cover?.addEventListener('change',()=>{const file=cover.files?.[0];if(!file)return;const reader=new FileReader();reader.onload=()=>{state.bookMeta.coverUrl=reader.result;renderMode();updatePreview()};reader.readAsDataURL(file)})};
  const importContent=(html,fileName='粘贴内容.html')=>{state.htmlContent=html;state.previewHtml=html;state.importMeta.fileName=fileName;const found=parseHtml(html);state.importMeta.structure=state.validationResult.html?'结构正常':'结构异常';renderMode();updatePreview();showToast(`已解析 ${fileName}`);return found};
  const bindManual=()=>{bindMeta();const editor=root.querySelector('#workshopHtml');const lines=root.querySelector('#editorLines');editor.addEventListener('input',()=>{state.htmlContent=editor.value;state.previewHtml=editor.value;lines.textContent=Array.from({length:Math.max(1,editor.value.split('\n').length)},(_,i)=>i+1).join('\n');updatePreview()});root.querySelector('[data-recognize]').addEventListener('click',()=>{parseHtml(state.htmlContent);renderMode();updatePreview();showToast('已尝试从 HTML 识别信息')});root.querySelector('[data-format]').addEventListener('click',()=>{state.htmlContent=formatHtml(state.htmlContent);renderMode();updatePreview();showToast('HTML 已格式化')});root.querySelector('[data-paste-html]').addEventListener('click',async()=>{try{const text=await navigator.clipboard.readText();if(text){state.htmlContent=text;renderMode();updatePreview();showToast('已粘贴剪贴板 HTML')}}catch{showToast('请直接在编辑器中粘贴 HTML')}})};
  const bindImport=()=>{bindMeta();const zone=root.querySelector('#dropZone'),fileInput=root.querySelector('#htmlFileInput'),paste=root.querySelector('#importHtmlText');const read=file=>{if(!file)return;const reader=new FileReader();reader.onload=()=>importContent(String(reader.result),file.name);reader.readAsText(file)};fileInput.addEventListener('change',()=>read(fileInput.files?.[0]));['dragenter','dragover'].forEach(name=>zone.addEventListener(name,e=>{e.preventDefault();zone.classList.add('dragging')}));['dragleave','drop'].forEach(name=>zone.addEventListener(name,e=>{e.preventDefault();zone.classList.remove('dragging')}));zone.addEventListener('drop',e=>read(e.dataTransfer?.files?.[0]));root.querySelector('[data-parse-paste]').addEventListener('click',()=>importContent(paste.value));paste.addEventListener('input',()=>{state.htmlContent=paste.value;state.previewHtml=paste.value;updatePreview()})};
  const blankModelForm=()=>({id:'',apiFormat:'openai-chat-completions',baseUrl:'https://api.openai.com/v1',useFullUrl:false,modelId:'',displayName:'',apiKey:'',activate:true});
  const renderSettings=()=>{const current=root.querySelector('#aiModelSettings');if(!current)return;current.outerHTML=AiModelSettings();if(!state.settingsOpen)return;root.querySelector('[data-close-model-settings]').onclick=()=>{state.settingsOpen=false;renderSettings()};root.querySelector('.model-settings-backdrop').onclick=event=>{if(event.target===event.currentTarget){state.settingsOpen=false;renderSettings()}};root.querySelector('[data-new-model]').onclick=()=>{state.modelForm=blankModelForm();state.modelMessage='';renderSettings()};root.querySelectorAll('[data-edit-model]').forEach(button=>button.onclick=()=>{const model=state.aiModels.find(item=>item.id===button.dataset.editModel);if(!model)return;state.modelForm={id:model.id,apiFormat:model.apiFormat,baseUrl:model.baseUrl,useFullUrl:model.useFullUrl,modelId:model.modelId,displayName:model.displayName,apiKey:'',activate:model.isActive};state.modelMessage='';renderSettings()});root.querySelectorAll('[data-model-field]').forEach(input=>input.addEventListener('input',()=>{state.modelForm[input.dataset.modelField]=input.type==='checkbox'?input.checked:input.value;if(input.dataset.modelField==='useFullUrl')renderSettings()}));root.querySelector('[data-reset-model]').onclick=()=>{state.modelForm=state.modelForm.id?{...state.modelForm,apiKey:''}:blankModelForm();state.modelMessage='';renderSettings()};root.querySelector('#modelSettingsForm').onsubmit=async event=>{event.preventDefault();const payload={apiFormat:state.modelForm.apiFormat,baseUrl:state.modelForm.baseUrl,useFullUrl:state.modelForm.useFullUrl,modelId:state.modelForm.modelId,displayName:state.modelForm.displayName,apiKey:state.modelForm.apiKey||undefined,activate:state.modelForm.activate};try{const saved=state.modelForm.id?await updateAiModel(state.modelForm.id,payload):await createAiModel(payload);state.modelForm={...state.modelForm,id:saved.id,apiKey:''};state.modelMessage='模型配置已安全保存';state.aiModels=await getAiModels();state.aiConfig=await getAiConfig();renderMode();renderSettings();showToast('模型配置已保存')}catch(error){state.modelMessage=error.message;renderSettings()}};root.querySelector('[data-activate-model]')?.addEventListener('click',async()=>{try{await activateAiModel(state.modelForm.id);state.aiModels=await getAiModels();state.aiConfig=await getAiConfig();state.modelForm.activate=true;state.modelMessage='已切换为当前模型';renderMode();renderSettings()}catch(error){state.modelMessage=error.message;renderSettings()}});root.querySelector('[data-test-model]')?.addEventListener('click',async()=>{state.modelMessage='正在发送测试请求…';renderSettings();try{const result=await testAiModel(state.modelForm.id);state.modelMessage=`连接成功 · ${result.latencyMs}ms · ${result.model}`;renderSettings()}catch(error){state.modelMessage=`连接失败：${error.message}`;renderSettings()}});root.querySelector('[data-delete-model]')?.addEventListener('click',async()=>{if(!confirm('确定删除这个模型配置？此操作无法撤销。'))return;try{await deleteAiModel(state.modelForm.id);state.aiModels=await getAiModels();state.aiConfig=await getAiConfig();state.modelForm=blankModelForm();state.modelMessage='模型配置已删除';renderMode();renderSettings()}catch(error){state.modelMessage=error.message;renderSettings()}})};
  const renderTemplateEditor=()=>{const current=root.querySelector('#templateEditor');if(!current)return;current.outerHTML=TemplateEditor();if(!state.templateEditorOpen||!state.templateForm)return;const close=()=>{state.templateEditorOpen=false;state.templateForm=null;state.templateMessage='';renderTemplateEditor()};root.querySelectorAll('[data-close-template-editor]').forEach(button=>button.onclick=close);root.querySelector('.template-editor-backdrop').onclick=event=>{if(event.target===event.currentTarget)close()};root.querySelectorAll('[data-template-field]').forEach(input=>input.addEventListener('input',()=>{state.templateForm[input.dataset.templateField]=input.value}));root.querySelectorAll('[data-template-module-field]').forEach(input=>input.addEventListener('input',()=>{state.templateForm.modules[Number(input.dataset.templateModuleIndex)][input.dataset.templateModuleField]=input.value}));root.querySelectorAll('[data-template-default]').forEach(input=>input.addEventListener('change',()=>{const key=state.templateForm.modules[Number(input.dataset.templateDefault)].key;state.templateForm.defaultModules=input.checked?[...new Set([...state.templateForm.defaultModules,key])]:state.templateForm.defaultModules.filter(item=>item!==key)}));root.querySelector('#templateEditorForm').onsubmit=async event=>{event.preventDefault();state.templateMessage='正在保存模板…';renderTemplateEditor();try{const saved=await updateAiTemplate(state.templateForm.id,{name:state.templateForm.name,description:state.templateForm.description,contentType:state.templateForm.contentType,systemPrompt:state.templateForm.systemPrompt,defaultModules:state.templateForm.defaultModules,modules:state.templateForm.modules});state.templates=state.templates.map(item=>item.id===saved.id?{...saved,systemPrompt:undefined,schemaVersion:undefined}:item);state.aiForm.modules=[...saved.defaultModules];state.templateEditorOpen=false;state.templateForm=null;renderTemplateEditor();renderMode();updateStats();showToast('模板已保存')}catch(error){state.templateMessage=error.message;renderTemplateEditor()}}};
  const openTemplateEditor=async()=>{const template=selectedTemplate();if(!template)return;try{const full=await getAiTemplate(template.id);state.templateForm=structuredClone(full);state.templateEditorOpen=true;state.templateMessage='';renderTemplateEditor()}catch(error){showError(error)}};
  const syncAiFormFromDom=()=>{root.querySelectorAll('[data-meta]').forEach(input=>{state.bookMeta[input.dataset.meta]=input.value});root.querySelectorAll('[data-ai-field]').forEach(input=>{state.aiForm[input.dataset.aiField]=input.type==='checkbox'?input.checked:input.value});state.aiForm.modules=[...root.querySelectorAll('[data-ai-module]:checked')].map(item=>item.dataset.aiModule)};
  const validateAiInput=()=>{const problems=[];if(!state.bookMeta.title.trim())problems.push('书名');if(!/^[a-z0-9]+(?:-[a-z0-9]+)*$/.test(state.bookMeta.slug.trim()))problems.push('合法 Slug（可点击 AI 填写）');if(!state.aiForm.modules.length)problems.push('至少一个内容模块');return problems};
  const bindMetadataFill=()=>{root.querySelector('[data-ai-fill-metadata]')?.addEventListener('click',async()=>{syncAiFormFromDom();const title=state.bookMeta.title.trim();if(!title){showToast('请先填写书名');root.querySelector('[data-meta="title"]')?.focus();return}state.metadataLoading=true;renderMode();try{const metadata=await completeBookMetadata(title);state.bookMeta.author=metadata.author||state.bookMeta.author;state.bookMeta.slug=metadata.slug;showToast(metadata.author?'作者和 Slug 已自动填写':'Slug 已自动填写，作者未能可靠识别')}catch(error){showError(error)}finally{state.metadataLoading=false;renderMode()}})};
  const bindAi=()=>{bindMeta();root.querySelector('[data-open-login]')?.addEventListener('click',()=>window.dispatchEvent(new CustomEvent('study-auth-required')));root.querySelector('[data-open-model-settings]')?.addEventListener('click',()=>{state.settingsOpen=true;state.modelMessage='';renderSettings()});root.querySelector('[data-edit-template]')?.addEventListener('click',openTemplateEditor);root.querySelector('[data-switch-import]')?.addEventListener('click',()=>switchMode('import'));root.querySelector('[data-switch-manual]')?.addEventListener('click',()=>switchMode('manual'));root.querySelector('[data-ai-template]')?.addEventListener('change',event=>{state.aiForm.templateId=event.target.value;const template=selectedTemplate();state.aiForm.modules=[...(template?.defaultModules||[])];renderMode()});root.querySelectorAll('[data-ai-field]').forEach(input=>input.addEventListener('input',()=>{state.aiForm[input.dataset.aiField]=input.type==='checkbox'?input.checked:input.value}));root.querySelectorAll('[data-ai-module]').forEach(input=>input.addEventListener('change',()=>{state.aiForm.modules=[...root.querySelectorAll('[data-ai-module]:checked')].map(item=>item.dataset.aiModule)}));root.querySelector('[data-generate-prompt]')?.addEventListener('click',()=>{state.prompt=makePrompt();root.querySelector('#promptOutput').textContent=state.prompt;showToast('Prompt 摘要已生成')});root.querySelector('[data-copy-prompt]')?.addEventListener('click',async()=>{if(!state.prompt)state.prompt=makePrompt();try{await navigator.clipboard.writeText(state.prompt),showToast('Prompt 摘要已复制')}catch{showToast('复制失败，请手动复制')}});root.querySelector('[data-ai-generate]')?.addEventListener('click',async event=>{syncAiFormFromDom();state.bookMeta.slug=state.bookMeta.slug.trim();const problems=validateAiInput();if(problems.length){showToast(`请补充或修正：${problems.join('、')}`);return}event.currentTarget.disabled=true;state.aiError='';try{const task=await createGeneration({title:state.bookMeta.title.trim(),slug:state.bookMeta.slug,author:state.bookMeta.author.trim(),...categoryInfo(),templateId:state.aiForm.templateId,modules:state.aiForm.modules,sourceText:state.aiForm.sourceText.trim(),audience:state.aiForm.audience,style:state.aiForm.style,length:state.aiForm.length,allowBackgroundKnowledge:state.aiForm.allowBackgroundKnowledge});applyGeneration(task);renderMode();pollGeneration(task.id);showToast('生成任务已创建')}catch(error){showError(error);renderMode()}});root.querySelector('[data-ai-cancel]')?.addEventListener('click',async()=>{try{applyGeneration(await cancelGeneration(state.generation.id));stopPolling();renderMode();showToast('任务已取消')}catch(error){showError(error)}});root.querySelectorAll('[data-regenerate-section]').forEach(button=>button.addEventListener('click',async()=>{const instruction=prompt('本次重新生成的额外要求（可留空）')||'';button.disabled=true;try{const task=await regenerateSection(state.generation.id,button.dataset.regenerateSection,instruction);applyGeneration(task);renderMode();showToast('模块已重新生成')}catch(error){showError(error);renderMode()}}));root.querySelectorAll('[data-load-generation]').forEach(button=>button.addEventListener('click',async()=>{try{const task=await getGeneration(button.dataset.loadGeneration);applyGeneration(task);renderMode();if(!['completed','failed','cancelled'].includes(task.status))pollGeneration(task.id)}catch(error){showError(error)}}))};
  const switchMode=mode=>{state.mode=mode;root.querySelectorAll('[data-creation-mode]').forEach(item=>item.classList.toggle('active',item.dataset.creationMode===mode));renderMode()};
  const renderMode=()=>{slot.innerHTML=state.mode==='manual'?ManualCreatePanel():state.mode==='import'?ImportHtmlPanel():state.mode==='history'?TaskHistoryPanel():AiGeneratePanel();if(state.mode==='manual')bindManual();else if(state.mode==='import')bindImport();else if(state.mode==='history')root.querySelectorAll('[data-load-generation]').forEach(button=>button.addEventListener('click',async()=>{try{state.mode='ai';applyGeneration(await getGeneration(button.dataset.loadGeneration));root.querySelectorAll('[data-creation-mode]').forEach(item=>item.classList.toggle('active',item.dataset.creationMode==='ai'));renderMode()}catch(error){showError(error)}}));else{bindAi();bindMetadataFill()}bindSharedActions()};
  root.querySelectorAll('[data-creation-mode]').forEach(btn=>btn.addEventListener('click',()=>{state.mode=btn.dataset.creationMode;root.querySelectorAll('[data-creation-mode]').forEach(x=>x.classList.toggle('active',x===btn));renderMode()}));
  const openPreview=event=>{previewReturnFocus=event?.currentTarget||document.activeElement;state.isFullscreenPreview=true;const drawer=root.querySelector('#previewDrawer');drawer.hidden=false;root.querySelector('#previewDrawerFrame').srcdoc=state.previewHtml;document.body.classList.add('preview-open');drawer.querySelector('.preview-close')?.focus()};
  const closePreview=()=>{state.isFullscreenPreview=false;const drawer=root.querySelector('#previewDrawer');if(drawer){drawer.hidden=true;const frame=root.querySelector('#previewDrawerFrame');if(frame)frame.srcdoc=''}document.body.classList.remove('preview-open');previewReturnFocus?.focus?.();previewReturnFocus=null};
  const saveDraftAction=async()=>{if(state.mode==='ai'&&state.generation?.status==='completed'){try{const result=await saveGenerationDraft(state.generation.id);state.generation.bookSlug=result.slug;showToast(`草稿已保存到服务器书库：${result.slug}`)}catch(error){showError(error)}return}try{validateBookInput();const result=await saveBookDraft(bookPayload());state.bookMeta.status='draft';localStorage.setItem('digital-study-workshop-draft',JSON.stringify({bookMeta:state.bookMeta,htmlContent:state.htmlContent}));showToast(`草稿已保存到服务器书库：${result.slug}`)}catch(error){showError(error);showToast('后端不可用时可使用“导出到本地 Git 目录”保留文件')}};
  const exportContentAction=async()=>{try{const path=await writeBookToContentDirectory(state.bookMeta.status==='published'?'published':'draft');if(path)showToast(`已写入 ${path}，请提交到 Git`)}catch(error){showError(error)}};
  const publishAction=async()=>{try{if(state.mode==='ai'&&state.generation?.status==='completed'){const result=await publishGeneration(state.generation.id,{syncToGit:state.syncToGit});state.generation.bookSlug=result.slug;state.bookMeta.status='published';showToast(result.gitSyncJob?.status==='error'?`《${state.bookMeta.title}》已发布，但 Git 同步未配置`:(state.syncToGit?`《${state.bookMeta.title}》已发布，Git 同步已排队`:`《${state.bookMeta.title}》已发布`));return}validateBookInput();const result=await publishBook({...bookPayload(),syncToGit:state.syncToGit});state.bookMeta.status='published';showToast(result.gitSyncJob?.status==='error'?`《${result.title}》已发布，但 Git 同步未配置`:(state.syncToGit?`《${result.title}》已发布，Git 同步已排队`:`《${result.title}》已发布到网站`))}catch(error){showError(error)}};
  const bindSharedActions=()=>{root.querySelectorAll('[data-sync-git]').forEach(input=>input.onchange=()=>{state.syncToGit=input.checked;root.querySelectorAll('[data-sync-git]').forEach(other=>{other.checked=state.syncToGit})});root.querySelectorAll('[data-open-preview]').forEach(btn=>btn.onclick=openPreview);root.querySelectorAll('[data-close-preview]').forEach(btn=>btn.onclick=closePreview);root.querySelectorAll('[data-export-content]').forEach(btn=>btn.onclick=exportContentAction);root.querySelectorAll('[data-save]').forEach(btn=>btn.onclick=saveDraftAction);root.querySelectorAll('[data-publish]').forEach(btn=>btn.onclick=publishAction);root.querySelectorAll('[data-revalidate]').forEach(btn=>btn.onclick=()=>{parseHtml(state.htmlContent,{apply:false});updatePreview();showToast('校验已更新')})};
  bindSharedActions();renderMode();updatePreview();
  updateStats();
  void loadAiData();
  root.querySelectorAll('[data-device]').forEach(btn=>btn.addEventListener('click',()=>{state.previewDevice=btn.dataset.device;root.querySelectorAll('[data-device]').forEach(x=>x.classList.toggle('active',x===btn));root.querySelector('#deviceFrame').className=`device-frame ${state.previewDevice}`}));
  if(window.__workshopEscapeHandler)window.removeEventListener('keydown',window.__workshopEscapeHandler);window.__workshopEscapeHandler=e=>{if(e.key==='Escape'&&state.isFullscreenPreview)closePreview()};window.addEventListener('keydown',window.__workshopEscapeHandler);
}
